from pathlib import Path
import hashlib
import json

root = Path('products/services/catalogue-inbound-cad')
for path in sorted(root.rglob('*')):
    if not path.is_file():
        continue
    data = path.read_bytes()
    print(f'{path} | {len(data)} bytes | sha256 {hashlib.sha256(data).hexdigest()}')
    if path.suffix == '.json':
        record = json.loads(data)
        if isinstance(record, dict):
            checks = record.get('checks', [])
            if isinstance(checks, list) and checks and all(isinstance(check, dict) for check in checks):
                print('Recorded checks:', sum(check.get('passed') is True for check in checks), 'of', len(checks))
            drafts = record.get('operator_reply_drafts')
            if isinstance(drafts, dict):
                print('Draft keys:', ', '.join(sorted(drafts)))
